            "vectorResizingFromQuarterInt8 through GenericAnySourcePair<BFloat16, Int8>"
        )
        let aInputs = Inputs.conversions(SIMD<Int8>.QuarterVector.self, seed: 0xD0EE_96B4_2501_7F30)
            .map(poisoningUpperBytes)
        for a in aInputs {
            let port = GenericAnySourcePair<BFloat16, Int8>.vector(resizing: a)
            let reference = H.vector(resizing: a)
            let definedBytes = SIMD<Int8>.QuarterVector.laneCount * MemoryLayout<Int8>.stride
            let grownBytes = H.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                MemoryLayout<SIMD<Int8>.QuarterVector.Raw>.size
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

