    @Test func halfVectorResizingFromUInt8ThroughPair() {
        let mismatches = Mismatches(
            "halfVectorResizingFromUInt8 through GenericAnySourcePair<BFloat16, UInt8>"
        )
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0x0A1B_13A1_62E3_D56C)
        for a in aInputs {
            let port = GenericAnySourcePair<BFloat16, UInt8>.halfVector(resizing: a)
            let reference = H.halfVector(resizing: a)
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.HalfVector.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

